import{_ as r}from"./chunks/overview-hero.D7m_mGxJ.js";import{_ as t,o as e,c as l,a3 as o}from"./chunks/framework.D1iekJsc.js";const _=JSON.parse('{"title":"환영","description":"MiniTavern Ultra 가이드 — 한 문장 캐릭터 카드와 v2/v3, GPT·Claude·OpenRouter 또는 로컬 모델, 월드북·정규식·프리셋, 사진 이해와 사진 답장, 백업과 채팅 아카이브.","frontmatter":{"title":"환영","description":"MiniTavern Ultra 가이드 — 한 문장 캐릭터 카드와 v2/v3, GPT·Claude·OpenRouter 또는 로컬 모델, 월드북·정규식·프리셋, 사진 이해와 사진 답장, 백업과 채팅 아카이브.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"환영 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra 가이드 — 한 문장 캐릭터 카드와 v2/v3, GPT·Claude·OpenRouter 또는 로컬 모델, 월드북·정규식·프리셋, 사진 이해와 사진 답장, 백업과 채팅 아카이브."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko"}]]},"headers":[],"relativePath":"ko/index.md","filePath":"ko/index.md","lastUpdated":1792058564000}'),i={name:"ko/index.md"};function n(u,a,s,d,h,g){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="환영" tabindex="-1">환영 <a class="header-anchor" href="#환영" aria-label="Permalink to &quot;환영&quot;">​</a></h1><div class="overview-hero"><p><img src="'+r+'" alt="MiniTavern Ultra"></p></div><h2 id="앱-소개" tabindex="-1">앱 소개 <a class="header-anchor" href="#앱-소개" aria-label="Permalink to &quot;앱 소개&quot;">​</a></h2><p><strong>MiniTavern Ultra</strong>는 <strong>AI 롤플레이 채팅</strong> 앱입니다.</p><p><strong>AI 파트너를 만들고, 이야기를 연기하세요</strong> — 한 문장으로 카드를 만들거나, 주류 v2·v3 카드를 가져옵니다.</p><p>GPT, Claude, OpenRouter와 집의 로컬 모델을 연결합니다. 키는 휴대폰에 두고, 채팅도 기기에 먼저 남습니다.</p><h2 id="할-수-있는-일" tabindex="-1">할 수 있는 일 <a class="header-anchor" href="#할-수-있는-일" aria-label="Permalink to &quot;할 수 있는 일&quot;">​</a></h2><ol><li><p><strong>한 문장으로 만들거나 v2 / v3를 가져오기</strong><br> 원하는 사람을 적으면 이름·성격·인사말이 나옵니다. 확인한 뒤 대화합니다. <a href="/ultra_guides/ko/manual/ai-create">AI로 만들기</a>. PNG / JSON은 주류 캐릭터 카드 v2, v3에 맞습니다. <a href="/ultra_guides/ko/manual/chara-card">캐릭터 카드</a>.</p></li><li><p><strong>GPT, Claude, OpenRouter 또는 로컬</strong><br> 내 키로 직결하거나 Ollama / LM Studio에 연결합니다. 키는 기기의 보안 저장소에 둡니다. <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>. 유료 한도가 없으면 <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>; PC 배포는 <a href="/ultra_guides/ko/local/">로컬 모델</a>.</p></li><li><p><strong>월드북, 정규식, 프리셋: 만들거나 가져오기</strong><br><a href="/ultra_guides/ko/manual/lorebook">월드북</a>이 설정을 지키고, <a href="/ultra_guides/ko/manual/regex">정규식</a>이 화면을 다듬고, <a href="/ultra_guides/ko/manual/presets">프리셋</a>이 프롬프트 구성을 바꿉니다. 새로 만들거나 가진 파일을 가져올 수 있습니다. 샘플링은 모델 설정에 있습니다.</p></li><li><p><strong>몰입 대화: 사진 이해, 인물 구분, 사진 답장</strong><br> 보낸 사진을 읽고 누구인지 구분합니다. 캐릭터도 장면에 맞춰 사진으로 답할 수 있습니다. <a href="/ultra_guides/ko/manual/chat">채팅</a>.</p></li><li><p><strong>백업과 채팅 아카이브</strong><br><a href="/ultra_guides/ko/manual/backup">전체 백업</a>으로 캐릭터·채팅·월드북·정규식을 옮깁니다. 키를 포함할지는 직접 정합니다. <a href="/ultra_guides/ko/manual/chat-archive">채팅 아카이브</a>는 기존 대화에 합치거나 새 채팅으로 엽니다.</p></li></ol><h2 id="왜-minitavern인가" tabindex="-1">왜 MiniTavern인가 <a class="header-anchor" href="#왜-minitavern인가" aria-label="Permalink to &quot;왜 MiniTavern인가&quot;">​</a></h2><ul><li><strong>카드가 빠름</strong>: 한 문장으로 만들거나 v2 / v3를 가져옴</li><li><strong>모델은 내 것</strong>: GPT, Claude, OpenRouter 또는 로컬. 키는 기기에</li><li><strong>장편 도구</strong>: 월드북, 정규식, 프리셋, 페르소나</li><li><strong>채팅이 봄</strong>: 사진, 인물, 사진 답장</li><li><strong>데이터 이동</strong>: 전체 백업과 단톡 아카이브</li></ul><h2 id="빠른-시작" tabindex="-1">빠른 시작 <a class="header-anchor" href="#빠른-시작" aria-label="Permalink to &quot;빠른 시작&quot;">​</a></h2><ol><li><strong>모델 설정</strong>: 설정 → <a href="/ultra_guides/ko/manual/model-link">모델 연결</a> → 새로 만들기·테스트 → 기본값.</li><li><strong>캐릭터</strong>: 캐릭터 카드 → <a href="/ultra_guides/ko/manual/chara-card">가져오기 / 만들기</a>.</li><li><strong>채팅</strong>: 캐릭터에서 열기 — 동반이든 연기든 선택.</li></ol><p>자세한 단계: <a href="/ultra_guides/ko/manual/getting-started">처음 사용</a>. PC 배포: <a href="/ultra_guides/ko/local/">로컬 개요</a> · <a href="/ultra_guides/ko/quickstart">30분 퀵스타트</a> · <a href="/ultra_guides/ko/local/image-gen/">이미지</a>. 무료 한도: <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>.</p><h2 id="매뉴얼-입구" tabindex="-1">매뉴얼 입구 <a class="header-anchor" href="#매뉴얼-입구" aria-label="Permalink to &quot;매뉴얼 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>구역</th><th>설명</th></tr></thead><tbody><tr><td><a href="/ultra_guides/ko/manual/">매뉴얼 홈</a></td><td>권장 읽기 순서·총괄</td></tr><tr><td><a href="/ultra_guides/ko/manual/model-link">모델</a></td><td>연결·파라미터·테스트·오류</td></tr><tr><td><a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a></td><td>각사 무료 한도와 Key 입력</td></tr><tr><td><a href="/ultra_guides/ko/local/">로컬 모델</a></td><td>언어 / 이미지 PC 배포</td></tr><tr><td><a href="/ultra_guides/ko/manual/chara-card">캐릭터</a> · <a href="/ultra_guides/ko/manual/ai-create">AI로 만들기</a></td><td>가져오기·편집·개채·설명으로 생성</td></tr><tr><td><a href="/ultra_guides/ko/manual/chat">채팅</a> · <a href="/ultra_guides/ko/manual/bubbles">말풍선과 입력창</a></td><td>대화·모양·세션 설정</td></tr><tr><td><a href="/ultra_guides/ko/manual/lorebook">고급</a> · <a href="/ultra_guides/ko/manual/presets">Presets</a></td><td>월드북·정규식·페르소나·Presets</td></tr></tbody></table><p>앱 내: 설정 → <strong>도움말과 피드백</strong> → <strong>사용자 매뉴얼</strong>.</p><h2 id="faq-요약" tabindex="-1">FAQ（요약） <a class="header-anchor" href="#faq-요약" aria-label="Permalink to &quot;FAQ（요약）&quot;">​</a></h2><p><strong>Q: MiniTavern Ultra란?</strong><br> A: AI 롤플레이 채팅 앱입니다. 한 문장으로 카드를 만들거나 v2 / v3를 가져오고, GPT, Claude, OpenRouter 또는 로컬 모델로 대화합니다. 키와 채팅은 기기에 먼저 남습니다.</p><p><strong>Q: 데이터가 서버로 올라가나요?</strong><br> A: 채팅·캐릭터·키 등은 기본적으로 기기에 둡니다. 모델 호출은 설정한 제3자 또는 로컬 주소로 갑니다. <a href="/ultra_guides/ko/privacy">개인정보</a>.</p><p><strong>Q: API 없이 쓸 수 있나요?</strong><br> A: 클라우드 Key를 준비하거나 <a href="/ultra_guides/ko/local/">로컬 모델</a>로 PC에 서비스를 올린 뒤 폰을 연결하세요. 무료 한도: <a href="/ultra_guides/ko/free-cloud/">무료 클라우드</a>; 로컬 이미지: <a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a>.</p><h2 id="다운로드·정책" tabindex="-1">다운로드·정책 <a class="header-anchor" href="#다운로드·정책" aria-label="Permalink to &quot;다운로드·정책&quot;">​</a></h2><ul><li>상단 <strong>MiniTavern 다운로드</strong> · <a href="https://minitavern.github.io/ultra_website/" target="_blank" rel="noreferrer">제품 공식 사이트</a></li><li><a href="/ultra_guides/ko/privacy">개인정보</a> · <a href="/ultra_guides/ko/terms">이용약관</a></li></ul>',22)])])}const f=t(i,[["render",n]]);export{_ as __pageData,f as default};
